AWS API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_api_gateway, "AWS API Gateway") {
    Component(REST_API_Endpoint, "REST API Endpoint", "AWS API Gateway", "Serves as the entry point for client requests, handling routing and edge security.")
    Component(AWS_Lambda_Authorizer, "AWS Lambda Authorizer", "AWS Lambda, Node.js", "Validates JWT tokens for incoming client requests.")
    Component(Request_Validator, "Request Validator", "AWS API Gateway native", "Schema-validates incoming JSON payloads to ensure structural integrity.")
    Component(Rate_Limiting_Module, "Rate Limiting Module", "AWS WAF / API Gateway Usage Plans", "Protects backend services by throttling excessive requests and mitigating abuse.")
}

Rel(REST_API_Endpoint, AWS_Lambda_Authorizer, "Validates JWT tokens", "In-memory invocation")
Rel(REST_API_Endpoint, Request_Validator, "Schema-validates JSON payloads", "Local execution")
Rel(REST_API_Endpoint, Rate_Limiting_Module, "Enforces rate limits and edge security", "AWS WAF integration")

@enduml

Amazon Aurora PostgreSQL Global Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_postgresql_global_database, "Amazon Aurora PostgreSQL Global Database") {
    Component(Primary_DB_Cluster, "Primary DB Cluster", "Amazon Aurora PostgreSQL", "Handles primary write operations, transactional consistency, and orchestrates cross-region replication.")
    Component(Secondary_DB_Clusters, "Secondary DB Clusters", "Amazon Aurora PostgreSQL", "Provides sub-10ms regional read operations across eu-west-1 and ap-southeast-1.")
    Component(Regional_Storage_Subsystem, "Regional Storage Subsystem", "Amazon Aurora Storage", "Persists encrypted transaction logs locally using region-bound AWS KMS CMKs.")
}

Rel(Primary_DB_Cluster, Secondary_DB_Clusters, "Replicates transactional data cross-region via dedicated AWS backbone infrastructure", "")
Rel(Primary_DB_Cluster, Regional_Storage_Subsystem, "Persists encrypted transaction logs locally", "")

@enduml
